"""Test recovery from small errors generated by the model near tip births."""
import argparse
from pathlib import Path

import numpy as np
import torch

from .model import GeometryFNO
from .tip_density import windows
from ..interface_events import match_births, tip_births
from ..rollout import evaluation_grid, forecast, single_loss, supervised_loss
from ..traditional.late_windows import WINDOWS
from ..trajectory_data import DEFAULT_DATA, Trajectories, augment
from ..trajectory_metrics import atomic_json, curve_difference, has_crossing, report_predictions


HORIZON = 8
DRIFT_STEPS = (4, 8)


def step(model, initial, state, previous, times, current):
    row = torch.arange(len(times), device=times.device)
    return model(initial, state, previous, times[row, current-1], times[row, current],
                 times[row, current+1, None])[:, 0]


@torch.no_grad()
def histories(model, data):
    initial, times, truth, records = data
    events = [min(r['matched_events'], key=lambda e: abs(e[0]-r['coarse_time'])) for r in records]
    birth = times.new_tensor([e[0] for e in events])
    anchor = (times == birth[:, None]).int().argmax(dim=1)-2
    if torch.any((anchor-max(DRIFT_STEPS) < 1) | (anchor+HORIZON >= times.shape[1])):
        raise ValueError('Window has insufficient history or follow-up')
    row = torch.arange(len(times), device=times.device)
    states = []
    for length in DRIFT_STEPS:
        current = anchor-length
        state, previous = truth[row, current], truth[row, current-1]
        for _ in range(length):
            previous, state = state, step(model, initial, state, previous, times, current)
            current = current+1
        states.append(torch.stack([previous, state], dim=1))
    return anchor, torch.stack(states, dim=1), events


def recovery_loss(model, data, cache, drift, batch=8):
    initial, times, truth, _ = data
    anchor, states, _ = cache
    device = times.device
    row = torch.randint(len(times), (batch,), device=device)
    choice = torch.randint(len(DRIFT_STEPS), (batch,), device=device)
    start = anchor[row]
    old, current = states[row, choice].unbind(1) if drift else (truth[row, start-1], truth[row, start])
    target = truth[row[:, None], start[:, None]+torch.arange(1, HORIZON+1, device=device)]
    first, previous, state, *labels = augment(initial[row], old, current, *target.unbind(1))
    losses = []
    for i, label in enumerate(labels):
        predicted = step(model, first, state, previous, times[row], start+i)
        losses.append(supervised_loss(predicted, label))
        previous, state = state, predicted
        if i == 3:
            previous, state = previous.detach(), state.detach()
    return torch.stack(losses).mean()


@torch.inference_mode()
def recovery_metrics(model, data, cache, clean=False):
    initial, times, truth, records = data
    anchor, states, events = cache
    row = torch.arange(len(times), device=times.device)
    indexes = anchor[:, None]+torch.arange(HORIZON+1, device=times.device)
    labels = truth[row[:, None], indexes].cpu().numpy()
    query = times[row[:, None], indexes].cpu().numpy()
    cases = []
    choices = [0] if clean else range(len(DRIFT_STEPS))
    for choice in choices:
        previous, state = (truth[row, anchor-1], truth[row, anchor]) if clean else states[:, choice].unbind(1)
        estimates = [state]
        for offset in range(HORIZON):
            previous, state = state, step(model, initial, state, previous, times, anchor+offset)
            estimates.append(state)
        predictions = torch.stack(estimates, dim=1).cpu().numpy()
        for record, event, ts, prediction, label in zip(records, events, query, predictions, labels):
            z = prediction[:, 0]+1j*prediction[:, 1]
            target = label[:, 0]+1j*label[:, 1]
            distances = [curve_difference(a[None], b[None], [0.])['maximum'] for a, b in zip(z, target)]
            matches = match_births(tip_births(z, ts), [event], time_limit=1.5)
            cases.append(dict(window=record['file'], drift_steps=0 if clean else DRIFT_STEPS[choice],
                              errors=distances, matches=matches, self_crossing=any(has_crossing(frame) for frame in z)))
    selected = cases if clean else [c for c in cases if .003 <= c['errors'][0] <= .05]
    if not selected:
        raise ValueError('No held-out histories in the declared mild-drift range')
    return dict(cases=cases, selected=len(selected),
                mean_errors=np.mean([c['errors'] for c in selected], axis=0).tolist(),
                contraction4=sum(c['errors'][4] < c['errors'][0] for c in selected),
                contraction8=sum(c['errors'][8] < c['errors'][0] for c in selected),
                matched=sum(len(c['matches']) for c in selected),
                self_crossing=sum(c['self_crossing'] for c in selected))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--warm', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('--arm', choices=['clean', 'drift'], required=True)
    parser.add_argument('--steps', type=int, default=1200)
    parser.add_argument('--recovery-weight', type=float, default=1.)
    parser.add_argument('--seed', type=int, required=True)
    args = parser.parse_args()
    if args.steps < 1 or not np.isfinite(args.recovery_weight) or args.recovery_weight <= 0:
        parser.error('Expected positive steps and a finite recovery weight')
    torch.set_num_threads(4)
    torch.manual_seed(args.seed)
    args.out.mkdir(parents=True, exist_ok=True)
    bank = Trajectories(DEFAULT_DATA, 1024, 'cuda', 100.)
    training, held_out = (windows(WINDOWS, bank, split) for split in ('train', 'test'))
    checkpoint = torch.load(args.warm, map_location='cuda', weights_only=True)
    model = GeometryFNO(**checkpoint['config']).cuda().eval()
    model.load_state_dict(checkpoint['model'])
    train_history, test_history = (histories(model, data) for data in (training, held_out))
    optimizer = torch.optim.AdamW(model.parameters(), lr=1.5e-4, weight_decay=1e-5)
    schedule = torch.optim.lr_scheduler.CosineAnnealingLR(optimizer, args.steps, eta_min=3e-5)
    grid = evaluation_grid(bank.times)
    history = []
    model.train()
    for count in range(1, args.steps+1):
        if count % 2:
            loss = single_loss(model, bank, grid, 3000+(count-1)//2, 8, long_rollout=True, initial_starts=True)
        else:
            loss = args.recovery_weight*recovery_loss(model, training, train_history, args.arm == 'drift')
        optimizer.zero_grad(set_to_none=True)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 1., error_if_nonfinite=True)
        optimizer.step()
        schedule.step()
        history.append(float(loss.detach()))
        if count in (1, args.steps) or count % 200 == 0:
            np.save(args.out/'history.npy', np.array(history))
            print(f'{args.arm} seed={args.seed} step={count} loss={np.mean(history[-200:]):.5g}', flush=True)
    model.eval()
    torch.save(dict(model=model.state_dict(), config=checkpoint['config'], nodes=1024,
                    horizon=100., step=args.steps, seed=args.seed), args.out/'model.pt')
    metrics = {key: recovery_metrics(model, held_out, test_history, clean=(key == 'clean'))
               for key in ('drift', 'clean')}
    frames = torch.arange(len(bank.times), device=bank.times.device)
    native = forecast(model, bank, bank.splits['test'], frames).cpu().numpy()
    atomic_json(args.out/'metrics.json', dict(seed=args.seed, arm=args.arm, steps=args.steps,
                    recovery_weight=args.recovery_weight,
                    **metrics, native=report_predictions(bank, 'test', native)))
    print('Completed recovery evaluation', flush=True)


if __name__ == '__main__':
    main()
